code.javascript:
function singleNonDuplicate(nums) {
  for (let i = 0; i < nums.length; i += 2) {
    if (i === nums.length - 1) return nums[i];
    if (nums[i] !== nums[i + 1]) return nums[i];
  }
  return nums[nums.length - 1];
}

